| التوحيد (0.5ن) | -وجوب التوحيد. -تحريم الشرك (0.5ن) |$sujet$,
  $sujet${"parties": [{"titre": "الأسئلة", "points": 20, "questions": [{"type": "libre", "numero": "1", "points": 0.5, "enonce": "حدد القضية الأساسية للوضعية.", "correction": "القضية الأساسية للوضعية: (سبل الحد من الانحرافات الفكرية والسلوكية)."}, {"type": "libre", "numero": "2 أ", "points": 0.5, "enonce": "عرف اصطلاحا المفهومين الآتيين: أ- الحياء:", "correction": "الحياء: انقباض النفس عن فعل ما يذم شرعا وعرفا، تعظيما لله وهيبة منه وإجلالا لنظره تعالى (0.5ن)"}, {"type": "libre", "numero": "2 ب", "points": 0.5, "enonce": "عرف اصطلاحا المفهومين الآتيين: ب- الفاحشة.", "correction": "الفواحش: ما عظم قبحه سواء كان ظاهرا كالزنا واللواط أو غيرهما أو باطنا كالرياء والعجب والنفاق (0.5ن)"}, {"type": "libre", "numero": "3", "points": 1, "enonce": "استخرج من الوضعية التقويمية أثرين من آثار الانحرافات الفكرية والسلوكية على الشباب.", "correction": "أن يستخرج من الوضعية أثرين من آثار الانحرافات الفكرية والسلوكية على الشباب: ( فساد الإيمان – ضياع القيم – انتهاك الفضيلة والمجاهرة بالفاحشة – ضياع قيم العفة والحياء... ) (0.5ن لكل أثر)"}, {"type": "libre", "numero": "4", "points": 1, "enonce": "تشاور أهل الفضل والعلم حول سبل الحد من الانحرافات تحصين للشباب من آثارها. أوضح أهمية التشاور في تعزيز الأمن الفكري والسلوكي لدى الناشئة.", "correction": "أن يوضح أهمية التشاور في تعزيز الأمن الفكري والسلوكي لدى الناشئة وحمايتهم من التصرفات المشينة والعدوانية والقيام بشؤونهم بما يحفظ حقوقهم ويرعى مصالحهم."}, {"type": "libre", "numero": "5", "points": 1, "enonce": "للأسرة دور كبير في حماية الأبناء من الانحراف. بين مكانتها في رعاية الأطفال وصيانة حقوقهم.", "correction": "أن يبين المكانة العظيمة للأسرة في الاسلام في رعاية الأطفال والقيام بكل شؤونهم على الوجه الأفضل، بما يحميهم من الانحراف الفكري والسلوكي، ويصون حقوقهم من الضياع."}, {"type": "libre", "numero": "6 أ", "points": 1, "enonce": "الايمان يحصن الناشئة من الانحراف، ويربيهم على الاعتدال والوسطية. أ- بين أثر الإيمان الحق في تحصين الفرد من الانحرافات الفكرية.", "correction": "أ- أثر الايمان في تحصين الفرد من الانحراف الفكري: إدراك الإنسان غاية خلقه و مقصد وجوده الأسمى في الدنيا والاستعداد لليوم الآخر مما يجعله مستحضرا على الدوام رقابة الله عز وجل في سره وعلانيته (1ن)"}, {"type": "libre", "numero": "6 ب", "points": 1, "enonce": "الايمان يحصن الناشئة من الانحراف، ويربيهم على الاعتدال والوسطية. ب – حدد ضابطين من ضوابط استغلال البيئة في الإسلام.", "correction": "بـ أن يحدد ضابطين من ضوابط استغلال البيئة في الإسلام: ( الاستغلال الرشيد لخيرات البيئة بلا إسراف ولا تبذير – الاعتدال والتوسط في الانتفاع بمواردها الطبيعية – تجنب كل أشكال التلوث البيئي...) (1ن)"}, {"type": "libre", "numero": "7", "points": 2, "enonce": "يدعو بعض الشباب إلى تبني أفكار وسلوكات مناقضة لثوابت الدين وقيمه، بدعوى التحرر ومسايرة العصر. حدد موقفك من هذه الدعوة مع التعليل المناسب.", "correction": "أن يبدي معارضته لدعوى تبني أفكار وسلوكات تناقض ثوابت الدين وقيمه بدعوى التحرر ومسايرة العصر معللا موقفه تعليلا شرعيا أو عقليا."}, {"type": "libre", "numero": "8", "points": 1, "enonce": "كفاءة الأسرة في رعاية الأبناء تجعلهم أهلا لتحمل أمانة الاستخلاف ومسؤولية عمارة الأرض. أبرز أهمية الوفاء بالأمانة والمسؤولية على نماء المجتمع وصلاحه.", "correction": "أن يبرز أن الوفاء بالأمانة والمسؤولية يؤدي إلى: ( نماء المجتمع وصلاحه ـ القضاء على مظاهر الفساد كالخيانة والغش وغيرهما ـ تحقيق الازدهار في كل المجالات \"التعليم – الصحة ...\" – نشر الثقة بين الناس...)"}, {"type": "libre", "numero": "9", "points": 1, "enonce": "التزام الأسرة مبدأ الكفاءة والاستحقاق يقي الأبناء من ثقافة الانحراف. بين كيف يقود هذا المبدأ إلى تحقيق عفة المجتمع.", "correction": "أن يبين أن التزام الأسرة بمبدأ الكفاءة والاستحقاق في الرعاية يؤدي إلى تحقيق عفة المجتمع وذلك من خلال تنمية قيم الاستعفاف والحياء بين أفراده، ووقايتهم من انهيار الأخلاق، وهتك الأعراض وانتشار الأمراض."}, {"type": "libre", "numero": "10", "points": 0.5, "enonce": "من مبادئ يعقوب عليه السلام في التربية الصبر على تصرفات أبنائه. استثمر ما ورد في سورة يوسف لتقديم موقفين لصبر يعقوب عليه السلام.", "correction": "أن يقدم موقفين لصبر يعقوب عليه السلام: ( صبر يعقوب عليه السلام على فراق يوسف عليه السلام – صبر يعقوب عليه السلام على فراق شقيق يوسف عليه السلام) (0.5ن لكل موقف)"}, {"type": "libre", "numero": "11 أ", "points": 2, "enonce": "منهج يعقوب عليه السلام في التربية أساسه التوجيه المستمر لأبنائه. استحضر من سورة يوسف الآيات المناسبة للمعاني الآتية: أ- توجيه يعقوب عليه السلام ليوسف بضرورة كتمان رؤياه، وتبشيره بالاصطفاء وإتمام النعمة.", "correction": "أن يستدل على المعاني الآتية بما يناسب من سورة يوسف: أ- ﴿قَالَ يَٰبُنَيِّ لَا تَقْصُصْ رُءْيَاكَ عَلَىٰٓ إِخْوَتِكَ فَيَكِيدُواْ لَكَ كَيْداً اِنَّ اَ۬لشَّيْطَٰنَ لِلِانسَٰنِ عَدُوٌّ مُّبِينٌ ۝٥ وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَاوِيلِ اِ۬لَاحَادِيثِ وَيُتِمُّ نِعْمَتَهُۥ عَلَيْكَ وَعَلَىٰٓ ءَالِ يَعْقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيْكَ مِن قَبْلُ إِبْرَٰهِيمَ وَإِسْحَٰقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ ۝٦﴾ (2ن)"}, {"type": "libre", "numero": "11 ب", "points": 2, "enonce": "منهج يعقوب عليه السلام في التربية أساسه التوجيه المستمر لأبنائه. استحضر من سورة يوسف الآيات المناسبة للمعاني الآتية: بـ توجيه يعقوب عليه السلام لأبنائه بضرورة التفرق أثناء الدخول إلى مصر حفاظا على سلامتهم.", "correction": "بـ ﴿وَقَالَ يَٰبَنِيَّ لَا تَدْخُلُواْ مِنۢ بَابٍ وَٰحِدٍ وَادْخُلُواْ مِنَ اَبْوَٰبٍ مُّتَفَرِّقَةٍ وَمَآ أُغْنِے عَنكُم مِّنَ اَ۬للَّهِ مِن شَےْءٍ اِنِ اِ۬لْحُكْمُ إِلَّا لِلَّهِ عَلَيْهِ تَوَكَّلْتُ وَعَلَيْهِ فَلْيَتَوَكَّلِ اِ۬لْمُتَوَكِّلُونَ ۝٦٧﴾ (2ن)"}, {"type": "libre", "numero": "12 أ", "points": 1, "enonce": "استثمر السند المصاحب للوضعية التقويمية في الإجابة على الآتي: أ- نقاط الخلاف بين الوفدين.", "correction": "أ- أن يبين أن نقاط الخلاف كانت حول كتابة البسملة ورد من جاء منهم الى المسلمين دون من ذهب منهم الى المشركين. (1ن)"}, {"type": "libre", "numero": "12 ب", "points": 1, "enonce": "استثمر السند المصاحب للوضعية التقويمية في الإجابة على الآتي: بـ الحكمة من موافقة رسول الله صلى الله عليه وسلم القرشيين على ترك البسملة ورد من جاء منهم الى المسلمين دون من ذهب منهم اليهم.", "correction": "بـ أن يشير إلى الحكمة من موافقة رسول الله صلى الله عليه وسلم المشركين: ( سياسة الحكمة والمرونة والحلم). (1ن)"}, {"type": "libre", "numero": "12 ج", "points": 1, "enonce": "استثمر السند المصاحب للوضعية التقويمية في الإجابة على الآتي: جـ نتيجتين من نتائج صلح الحديبية.", "correction": "جـ أن يستحضر نتيجتين من نتائج صلح الحديبية: ( خمود فتنة المنافقين – تبعثر القبائل الوثنية – ضمان حياد قريش – اتساع نشاط المسلمين الثقافي والسياسي والعسكري – دخول القبائل في الإسلام...) (1ن)"}, {"type": "tableau", "numero": "13-1", "points": 1, "enonce": "استنبط ما تضمنته الآيتين الكريمتين أدناه من قيم وأحكام وفق الجدول الآتي: النص الشرعي: قال تعالى: ﴿قَالَ اِ۬جْعَلْنِے عَلَىٰ خَزَآئِنِ اِ۬لَارْضِ إِنِّے حَفِيظٌ عَلِيمٌ ۝﴾ سورة يوسف", "champs": [{"libelle": "القيم", "reponse": "-الامانة -العلم (0.5ن)"}, {"libelle": "الأحكام الشرعية", "reponse": "-جواز طلب تحمل المسؤولية (0.5ن)"}]}, {"type": "tableau", "numero": "13-2", "points": 1, "enonce": "استنبط ما تضمنته الآيتين الكريمتين أدناه من قيم وأحكام وفق الجدول الآتي: النص الشرعي: قال تعالى: ﴿وَاتَّبَعْتُ مِلَّةَ ءَابَآءِيَ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ مَا كَانَ لَنَآ أَن نُّشْرِكَ بِاللَّهِ مِن شَےْءٍ﴾ سورة يوسف", "champs": [{"libelle": "القيم", "reponse": "التوحيد (0.5ن)"}, {"libelle": "الأحكام الشرعية", "reponse": "-وجوب التوحيد. -تحريم الشرك (0.5ن)"}]}], "texte": "### الوضعية التقويمية:\n\nفي ظل الانتشار المتسارع لوسائل الإغراء وضعف الرقابة الأسرية، تبنى بعض شباب اليوم أفكارا وسلوكات مناقضة لثوابت الدين وقيمه بدعوى التحرر ومسايرة العصر، أفسدت الإيمان وأضاعت القيم، حيث شاعت الفاحشة وانتهكت الفضيلة واضمحلت قيم العفة والحياء، وعم إسفاف لا يليق بأخلاق المسلم. ولخطورة هذا النوع من الانحراف كان لزاما تكثيف المشاورات بين أهل العلم والفضل للتفاوض حول سبل تعزيز الأمن الفكري والسلوكي للناشئة، مؤكدين على أهمية الايمان الحق والعلم الصحيح في تحصينهم من الانحراف، وتربيتهم على الاعتدال والوسطية، بغية بناء جيل قادر على بناء أسرة مستقرة تضمن للزوجين الاستقرار النفسي والاجتماعي، وتمنحهم القدرة على رعاية شؤون الأطفال ووقايتهم من ثقافة الانحراف بكفاءة واستحقاق. مقتدين بالمنهج التربوي لنبي الله يعقوب عليه السلام القائم على قيم الصبر والعفو والتسامح والتوجيه المستمر في التعامل مع تصرفات أبنائه. وبالرسول صلى الله عليه وسلم في تعامله مع أهله. مما يجعلهم أهلا لتحمل أمانة الاستخلاف ومسؤولية عمارة الأرض، مستلهمين الصفات القيادية ليوسف عليه السلام الذي استطاع بفضلها إدارة الأزمة الاقتصادية لمصر حين تولى أمر خزائن مصر بيقين مطلق بنصر الله والتمكين له.\n\n### السند:\n\n(...وعند الشروع في وضع الصيغة النهائية للمعاهدة وكتابتها لتكون نافذة المفعول رسميا حدث خلاف بين الوفدين على بعض النقاط،...ولكن النبي صلى الله عليه وسلم تمشيا مع سياسة الحكمة والمرونة والحلم،...وافق المشركين على ترك كتابة البسملة، وكذا وافقهم في كتابة محمد بن عبد الله وترك كتابة رسول الله ـ صلى الله عليه وسلم ـ، وكذا وافقهم في رد من جاء منهم إلى المسلمين دون من ذهب منهم إليهم، وإنما وافقهم في هذه الأمور للمصلحة المهمة الحاصلة بالصلح، تعليل ذلك والحكمة فيه في هذا الحديث بقوله: «من ذهب منا إليهم فأبعده الله، ومن جاءنا منهم سيجعل الله له فرجا ومخرجا »)\n\n*السيرة النبوية: عرض وقائع وتحليل أحداث، دروس وعبر لعلي الصلابي، ج2، ص300.*", "consigne": "إقرأ الوضعية و السند المصاحب، ثم أجب عن الأسئلة المرافقة:"}]}$sujet$::jsonb
)
on conflict (matiere, annee, session, coalesce(academie, ''))
